define(["mod_graphitoubb/afd_simulator"],function(t){var r=[],n=null;return{setAutomaton:function(t){n=t},testWord:function(e){if(!n)return null;var u=t.run(n,e),o={word:e,accepted:u.accepted,trace:u.trace};return r.push(o),o},getWords:function(){return r.slice()}}});